                if (dp2[s][l] == BigInteger.ZERO) continue
                val p = s + l
                if (p > n) continue
                val rem = n - p
                val cur = dp2[s][l]
                // Option 1: count[i] = i
                if (i <= rem) {
                    val ways = C[rem][i]
                    ndp2[s + i][l] = (ndp2[s + i][l] + cur * ways) % MOD
