                    if (c == i) continue
                    val ways = C[rem][c]
                    ndp2[s][l + c] = (ndp2[s][l + c] + cur * ways) % MOD
                }
            }
        }
        for (r in 0..n) System.arraycopy(ndp2[r], 0, dp2[r], 0, n + 1)
    }

    println(dp2[n - k][k] % MOD)
